	inline bool writeDropped(uint32_t from) {
		size_t lo = 0, hi = sizeof(WriteDrop) / sizeof(WriteDrop[0]);
		while (lo < hi) {
			size_t mid = (lo + hi) / 2;
			if (WriteDrop[mid] < from)
				lo = mid + 1;
			else
				hi = mid;
		}
		return lo < sizeof(WriteDrop) / sizeof(WriteDrop[0]) && WriteDrop[lo] == from;
	}

	// Binary search; returns `from` itself for an offset that isn't listed.
	inline uint32_t translate(uint32_t from) {
		size_t lo = 0, hi = sizeof(Entries) / sizeof(Entries[0]);
		while (lo < hi) {
			size_t mid = (lo + hi) / 2;
			if (Entries[mid].from < from)
				lo = mid + 1;
			else
				hi = mid;
		}
		return lo < sizeof(Entries) / sizeof(Entries[0]) && Entries[lo].from == from ? Entries[lo].to : from;
	}
